# AAC EDA
import pandas as pd

# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
df = pd.read_csv("datasets/aac_intakes_outcomes.csv")
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
#Remove columns
df = df.drop(columns=["age_upon_outcome_(years)", "age_upon_outcome_age_group", "outcome_month", "outcome_year", "outcome_monthyear", "outcome_weekday", "outcome_hour", "outcome_number", "dob_monthyear", "count", "age_upon_intake_(years)", "age_upon_intake_age_group", "intake_year", "intake_monthyear", "intake_weekday", "intake_hour", "time_in_shelter_days", "dob_year", "dob_month", "age_upon_intake"])
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
#Drop duplicates
df = df.drop_duplicates()
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
# Change foster adoptions to foster and drop outcome_subtype
foster_adoptions = (df["outcome_type"] == "Adoption") & (df["outcome_subtype"] == "Foster")
df.loc[foster_adoptions, "outcome_type"] = "Foster"
df = df.drop(columns=["outcome_subtype"])
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
#convert age_upon_outcome_(days) and age_upon_intake_(days) to age_upon_outcome_(years) and age_upon_intake_(years)
df["age_upon_outcome_(years)"] = df["age_upon_outcome_(days)"] / 365
df["age_upon_intake_(years)"] = df["age_upon_intake_(days)"] / 365
df = df.drop(columns=["age_upon_outcome_(days)", "age_upon_intake_(days)"])
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
# Convert time_in_shelter to numeric values
df["time_in_shelter"] = pd.to_timedelta(df["time_in_shelter"])
df["time_in_shelter_days"] = df["time_in_shelter"].dt.total_seconds() / (60 * 60 * 24)
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
#Compare neutered vs not neutered and time_in_shelter
def neuter_status(sex):
    '''
    Categorizes animals by neuter/spay status
    '''
    if "Neutered" in str(sex) or "Spayed" in str(sex):
        return "Neutered/Spayed"
    elif "Intact" in str(sex):
        return "Not Neutered/Spayed"
    else:
        return "Unknown"

# Create a new column for neuter status
df["neuter_status"] = df["sex_upon_intake"].apply(neuter_status)
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
# Narrow down to Female, Male or Other
def sex_status(sex):
    if "Male" in str(sex):
        return "Male"
    elif "Female" in str(sex):
        return "Female"
    else:
        return "Unknown"
# Create a new column for sex status
df["sex_status"] = df["sex_upon_intake"].apply(sex_status)

# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
# Remove pregnant, nursing from intake_condition
def clean_intake_condition(condition):
    if "Pregnant" in str(condition) or "Nursing" in str(condition):
        return "Pregnant/Nursing"
    else:
        return condition
    
df["intake_condition"] = df["intake_condition"].apply(clean_intake_condition)
# ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
df = df.drop(columns=["age_upon_outcome", "animal_id_intake", "animal_id_outcome", "date_of_birth", "outcome_datetime", "found_location", "intake_number", "age_upon_outcome_(years)", "age_upon_intake_(years)", "time_in_shelter"])
#------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
df = df[df["animal_type"].isin(["Dog", "Cat"])]
#------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
print(df.columns.tolist())
print(df['animal_type'].unique())